589	uint64_t SegmentImpl::doc_count(const IndexFilter::Ptr filter) {
590	  uint64_t doc_count = doc_ids_.size();
591	  if (filter) {
592	    for (const auto &doc_id : doc_ids_) {
593	      if (filter->is_filtered(doc_id)) {
594	        doc_count--;
595	      }
596	    }
597	  }
598	
599	  return doc_count;
600	}
