608	template <typename ValueType>
609	Status SegmentImpl::InsertScalar(InvertedColumnIndexer::Ptr &indexer,
610	                                 const Doc &doc,
611	                                 const FieldSchema::Ptr &field) {
612	  auto value = doc.get<ValueType>(field->name());
613	  auto segment_doc_id = doc_ids_.size();
614	  if (value.has_value()) {
615	    if constexpr (std::is_same_v<ValueType, std::vector<bool>>) {
616	      return indexer->insert(segment_doc_id, value.value());
617	    } else if constexpr (std::is_same_v<ValueType, std::vector<std::string>>) {
618	      return indexer->insert(segment_doc_id, value.value());
619	    } else if constexpr (is_vector<ValueType>::value) {
620	      const auto &vec = value.value();
621	      std::string value_str(
622	          reinterpret_cast<const char *>(vec.data()),
623	          vec.size() * sizeof(typename ValueType::value_type));
624	      return indexer->insert(segment_doc_id, value_str);
625	    } else if constexpr (std::is_same_v<ValueType, std::string>) {
626	      const ValueType &val = value.value();
627	      return indexer->insert(segment_doc_id, val);
628	    } else if constexpr (std::is_same_v<ValueType, bool>) {
629	      const ValueType &val = value.value();
630	      return indexer->insert(segment_doc_id, val);
631	    } else {
632	      const ValueType &val = value.value();
633	      std::string value_str(reinterpret_cast<const char *>(&val),
634	                            sizeof(ValueType));
635	      return indexer->insert(segment_doc_id, value_str);
636	    }
637	  } else {
638	    return indexer->insert_null(segment_doc_id);
639	  }
640	  return Status::OK();
641	}
