644	Status SegmentImpl::InsertVector(VectorColumnIndexer::Ptr &indexer,
645	                                 const Doc &doc,
646	                                 const FieldSchema::Ptr &field) {
647	  auto value = doc.get<ValueType>(field->name());
648	  if (value.has_value()) {
649	    vector_column_params::VectorData vector_data;
650	    if constexpr (std::is_same_v<ValueType,
651	                                 std::pair<std::vector<uint32_t>,
652	                                           std::vector<float16_t>>>) {
653	      const std::vector<uint32_t> &sparse_indices = value.value().first;
654	      const std::vector<float16_t> &sparse_value = value.value().second;
655	      vector_data.vector = vector_column_params::SparseVector{
656	          (uint32_t)sparse_indices.size(), (void *)sparse_indices.data(),
657	          (void *)sparse_value.data()};
658	    } else if constexpr (std::is_same_v<ValueType,
659	                                        std::pair<std::vector<uint32_t>,
660	                                                  std::vector<float>>>) {
661	      const std::vector<uint32_t> &sparse_indices = value.value().first;
662	      const std::vector<float> &sparse_value = value.value().second;
663	      vector_data.vector = vector_column_params::SparseVector{
664	          (uint32_t)sparse_indices.size(), (void *)sparse_indices.data(),
665	          (void *)sparse_value.data()};
666	    } else {
667	      vector_data.vector =
668	          vector_column_params::DenseVector{value.value().data()};
669	    }
670	
671	    auto &mem_block_meta = segment_meta_->writing_forward_block().value();
672	    auto &block_doc_id = mem_block_meta.doc_count_;
673	
674	    return indexer->Insert(vector_data, block_doc_id);
675	  } else {
676	    LOG_WARN("Field %s not found or is null for doc: %s", field->name().c_str(),
677	             doc.to_detail_string().c_str());
678	  }
679	  return Status::OK();
