682	Status SegmentImpl::insert_scalar_indexer(Doc &doc) {
683	  for (const auto &field : collection_schema_->forward_fields()) {
684	    auto index_type = field->index_type();
685	    if (index_type != IndexType::INVERT) {
686	      continue;
687	    }
688	    auto indexer = get_scalar_indexer(field->name());
689	    if (!indexer) {
690	      return Status::InternalError("Field ", field->name(), " indexer is null");
691	    }
692	    Status status;
693	    auto data_type = field->data_type();
694	    switch (field->data_type()) {
695	      case DataType::BINARY: {
696	        status = InsertScalar<std::string>(indexer, doc, field);
697	        break;
698	      }
699	      case DataType::STRING: {
700	        status = InsertScalar<std::string>(indexer, doc, field);
701	        break;
702	      }
703	      case DataType::BOOL:
704	        status = InsertScalar<bool>(indexer, doc, field);
705	        break;
706	      case DataType::INT32:
707	        status = InsertScalar<int32_t>(indexer, doc, field);
708	        break;
709	      case DataType::INT64:
710	        status = InsertScalar<int64_t>(indexer, doc, field);
711	        break;
712	      case DataType::UINT32:
713	        status = InsertScalar<uint32_t>(indexer, doc, field);
714	        break;
715	      case DataType::UINT64:
716	        status = InsertScalar<uint64_t>(indexer, doc, field);
717	        break;
718	      case DataType::FLOAT:
719	        status = InsertScalar<float>(indexer, doc, field);
720	        break;
721	      case DataType::DOUBLE:
722	        status = InsertScalar<double>(indexer, doc, field);
723	        break;
724	      case DataType::ARRAY_BINARY:
725	        status = InsertScalar<std::vector<std::string>>(indexer, doc, field);
726	        break;
727	      case DataType::ARRAY_STRING:
728	        status = InsertScalar<std::vector<std::string>>(indexer, doc, field);
729	        break;
730	      case DataType::ARRAY_BOOL:
731	        status = InsertScalar<std::vector<bool>>(indexer, doc, field);
732	        break;
733	      case DataType::ARRAY_INT32:
734	        status = InsertScalar<std::vector<int32_t>>(indexer, doc, field);
735	        break;
736	      case DataType::ARRAY_INT64:
737	        status = InsertScalar<std::vector<int64_t>>(indexer, doc, field);
738	        break;
739	      case DataType::ARRAY_UINT32:
740	        status = InsertScalar<std::vector<uint32_t>>(indexer, doc, field);
741	        break;
742	      case DataType::ARRAY_UINT64:
743	        status = InsertScalar<std::vector<uint64_t>>(indexer, doc, field);
744	        break;
745	      case DataType::ARRAY_FLOAT:
746	        status = InsertScalar<std::vector<float>>(indexer, doc, field);
747	        break;
748	      case DataType::ARRAY_DOUBLE:
749	        status = InsertScalar<std::vector<double>>(indexer, doc, field);
750	        break;
751	      default:
752	        status = Status::InternalError("unsupport data type ",
753	                                       DataTypeCodeBook::AsString(data_type));
754	    }
755	    if (!status.ok()) {
756	      LOG_ERROR("insert scalar failed[%s]", status.message().c_str());
757	      return status;
758	    }
759	  }
760	  return Status::OK();
761	}
