763	Status SegmentImpl::insert_vector_indexer(Doc &doc) {
764	  for (const auto &field : collection_schema_->vector_fields()) {
765	    std::vector<VectorColumnIndexer::Ptr> indexers;
766	    auto m_indexer = get_memory_vector_indexer(field->name());
767	    if (!m_indexer) {
768	      LOG_ERROR("vector indexer not found for field %s", field->name().c_str());
769	      return Status::InternalError("vector indexer not found for field: ",
770	                                   field->name());
771	    }
772	    indexers.push_back(m_indexer);
773	    auto vector_index_params =
774	        std::dynamic_pointer_cast<VectorIndexParams>(field->index_params());
775	    if (vector_index_params->quantize_type() != QuantizeType::UNDEFINED) {
776	      m_indexer = get_memory_quant_vector_indexer(field->name());
777	      if (!m_indexer) {
778	        LOG_ERROR("quant vector indexer not found for field %s",
779	                  field->name().c_str());
780	        return Status::InternalError(
781	            "quant vector indexer not found for field: ", field->name());
782	      }
783	      indexers.push_back(m_indexer);
784	    }
785	
786	    for (auto indexer : indexers) {
787	      Status status;
788	      auto data_type = field->data_type();
789	      switch (data_type) {
790	        case DataType::VECTOR_BINARY32:
791	          status = InsertVector<std::vector<uint32_t>>(indexer, doc, field);
792	          break;
793	        case DataType::VECTOR_BINARY64:
794	          status = InsertVector<std::vector<uint64_t>>(indexer, doc, field);
795	          break;
796	        case DataType::VECTOR_FP16:
797	          status = InsertVector<std::vector<float16_t>>(indexer, doc, field);
798	          break;
799	        case DataType::VECTOR_FP32:
800	          status = InsertVector<std::vector<float>>(indexer, doc, field);
801	          break;
802	        case DataType::VECTOR_FP64:
803	          status = InsertVector<std::vector<double>>(indexer, doc, field);
804	          break;
805	        // case DataType::VECTOR_INT4:
806	        //   status = InsertVector<std::vector<int8_t>>(indexer, doc, field);
807	        //   break;
808	        case DataType::VECTOR_INT8:
809	          status = InsertVector<std::vector<int8_t>>(indexer, doc, field);
810	          break;
811	        case DataType::VECTOR_INT16:
812	          status = InsertVector<std::vector<int16_t>>(indexer, doc, field);
813	          break;
814	        case DataType::SPARSE_VECTOR_FP16:
815	          status = InsertVector<
816	              std::pair<std::vector<uint32_t>, std::vector<float16_t>>>(
817	              indexer, doc, field);
818	          break;
819	        case DataType::SPARSE_VECTOR_FP32:
820	          status = InsertVector<
821	              std::pair<std::vector<uint32_t>, std::vector<float>>>(indexer,
822	                                                                    doc, field);
823	          break;
824	        default:
825	          status = Status::InvalidArgument(
826	              "unsupport data type", DataTypeCodeBook::AsString(data_type));
827	      }
828	      if (!status.ok()) {
829	        LOG_ERROR("insert vector failed[%s]", status.message().c_str());
830	        return status;
831	      }
832	    }
833	  }
834	  return Status::OK();
835	}
