837	Status SegmentImpl::internal_insert(Doc &doc) {
838	  uint64_t g_doc_id = doc_id_allocator_.fetch_add(1);
839	  doc.set_doc_id(g_doc_id);
840	
841	  if (ready_for_dump_block()) {
842	    auto s = flush();
843	    CHECK_RETURN_STATUS(s);
844	  }
845	
846	  // init writing memory components
847	  if (!memory_store_) {
848	    auto s = init_memory_components();
849	    CHECK_RETURN_STATUS(s);
850	  }
851	
852	  // write idmap
853	  auto s = id_map_->upsert(doc.pk(), g_doc_id);
854	  CHECK_RETURN_STATUS(s);
855	
856	  // write forward
857	  s = memory_store_->insert(doc);
858	  CHECK_RETURN_STATUS(s);
859	
860	  // write scalar index
861	  s = insert_scalar_indexer(doc);
862	  if (!s.ok() && s.code() != StatusCode::ALREADY_EXISTS) {
863	    return s;
864	  }
865	  // write FTS index
866	  s = insert_fts_indexer(doc);
867	  CHECK_RETURN_STATUS(s);
868	  // write vector index
869	  s = insert_vector_indexer(doc);
870	  if (!s.ok() && s != Status::AlreadyExists()) {
871	    return s;
872	  }
873	
874	  auto &mem_block = segment_meta_->writing_forward_block().value();
875	  mem_block.max_doc_id_ = g_doc_id;
876	  mem_block.doc_count_ = mem_block.doc_count_ + 1;
877	
878	  doc_ids_.push_back(g_doc_id);
879	
880	  return Status::OK();
881	}
