903	Status SegmentImpl::Insert(Doc &doc) {
904	  std::lock_guard lock(seg_mtx_);
905	
906	  if (id_map_ && id_map_->has(doc.pk())) {
907	    return Status::AlreadyExists("insert failed: doc_id[", doc.pk(),
908	                                 "] already exists in collection");
909	  }
910	
911	  doc.set_operator(Operator::INSERT);
912	
913	  // append wal
914	  auto s = append_wal(doc);
915	  CHECK_RETURN_STATUS(s);
916	
917	  return internal_insert(doc);
918	}
