950	Status SegmentImpl::Delete(const std::string &pk) {
951	  std::lock_guard lock(seg_mtx_);
952	
953	  uint64_t g_doc_id;
954	  if (!id_map_->has(pk, &g_doc_id)) {
955	    return Status::NotFound("primary key: ", pk, " not found");
956	  }
957	  if (delete_store_->is_deleted(g_doc_id)) {
958	    return Status::NotFound("primary key: ", pk, " g_doc_id: ", g_doc_id,
959	                            " already deleted");
960	  }
961	
962	  Doc mutable_doc;
963	  mutable_doc.set_pk(pk);
964	  mutable_doc.set_doc_id(g_doc_id);
965	  mutable_doc.set_operator(Operator::DELETE);
966	
967	  // append wal
968	  auto s = append_wal(mutable_doc);
969	  CHECK_RETURN_STATUS(s);
970	
971	  return internal_delete(mutable_doc);
972	}
